SELECT
FROM herb_collection_task t LEFT JOIN herb_batch b ON b.task_id = t.id AND b.is_deleted = 0
GROUP BY t.id ORDER BY t.created_at DESC LIMIT #{offset}, #{pageSize}

SELECT
FROM herb_collection_task t LEFT JOIN herb_batch b ON b.task_id = t.id AND b.is_deleted = 0
